<div class="recharge-history-list"><?php foreach($adminOrders['orders'] as $order) { [$tone,$label,$copy]=panicRechargeStatus($order); ?><article class="recharge-order" data-order-state="<?php echo $tone; ?>"><div class="recharge-order-top"><span><?php echo panicAccountEscape(panicRechargeArgDate($order['created_at'])); ?> ARG · <?php echo $order['live']?'Producción':'Prueba'; ?></span><span class="recharge-status"><?php echo panicAccountEscape($label); ?></span></div><div class="recharge-order-value"><strong><?php echo panicAccountEscape($order['account']); ?><small> <?php echo number_format($order['coins'],0,',','.'); ?> Eryns</small></strong><b>$ <?php echo number_format($order['price_cents']/100,0,',','.'); ?> ARS</b></div><p><?php echo panicAccountEscape($copy); ?></p><details><summary>Detalle de compra y entrega</summary><ul><?php foreach($order['lines'] as $line) { ?><li><?php echo $line['quantity']; ?> × <?php echo panicAccountEscape(panicAccountCurrencyLabel($line['title'])); ?><?php if($line['bonus']>0) { ?> · <?php echo number_format($line['bonus'],0,',','.'); ?> de bono por paquete<?php } ?></li><?php } ?></ul><p class="recharge-order-reference"><?php echo $order['id']; ?><br>Pago: <?php echo panicAccountEscape($order['payment_id'] ?? 'Sin confirmar'); ?></p><?php if(isset($order['before_coin'],$order['after_coin'])) { ?><p>Saldo: <?php echo number_format($order['before_coin'],0,',','.'); ?> → <?php echo number_format($order['after_coin'],0,',','.'); ?> Eryns<br>Entrega: <?php echo panicAccountEscape(panicRechargeArgDate($order['credited_at'])); ?> ARG</p><?php } ?><?php if($order['checked_at']) { ?><p>Última consulta: <?php echo panicAccountEscape(panicRechargeArgDate($order['checked_at'])); ?> ARG</p><?php } ?><?php if($order['error'] || $order['check_error']) { ?><p class="shop-error">Comprobación pendiente: <?php echo panicAccountEscape($order['check_error'] ?? $order['error']); ?></p><?php } ?></details><?php if($adminGateway && $order['payment_id'] && $order['live']===($adminSettings['environment']==='production')) { ?><form method="post" action="<?php echo panicAccountEscape($adminUrl.'?'.http_build_query(['buscar'=>$adminFilters['query'],'estado'=>$adminFilters['state'],'ambiente'=>$adminFilters['environment'],'pagina'=>$adminPage]).'#shop-orders'); ?>"><input type="hidden" name="admin_csrf" value="<?php echo $_SESSION['shop_admin_csrf']; ?>"><input type="hidden" name="order_id" value="<?php echo $order['id']; ?>"><button class="recharge-text-button" name="admin_action" value="check">Consultar pago en Ualá</button></form><?php } ?></article><?php } ?></div>
